k8s-config-projection.solution:
def buildEnv(sources, envFrom, env):
    def valid(name):
        if not name:
            return False
        if not (name[0].isascii() and (name[0].isalpha() or name[0] == "_")):
            return False
        return all(ch.isascii() and (ch.isalnum() or ch == "_") for ch in name)

    result = {}
    for src in envFrom:
        data = sources.get(src["name"])
        if data is None:
            if src.get("optional"):
                continue
            return "CreateContainerConfigError: " + src["name"]
        for key, value in data.items():
            name = (src.get("prefix") or "") + key
            if valid(name):
                result[name] = value
    for e in env:
        if "value" in e:
            result[e["name"]] = e["value"]
            continue
        data = sources.get(e["from"])
        if data is None or e["key"] not in data:
            if e.get("optional"):
                continue
            return "CreateContainerConfigError: %s/%s" % (e["from"], e["key"])
        result[e["name"]] = data[e["key"]]
    return result

k8s-pod-phase.solution:
def podStatus(pod):
    if pod.get("nodeName") is None:
        return ["Pending", "Pending"]
    policy = pod["restartPolicy"]
    containers = pod["containers"]

    def will_restart(c):
        return policy == "Always" or (policy == "OnFailure" and c.get("exitCode", 0) != 0)

    terminated = [c for c in containers if c["state"] == "terminated"]
    if len(terminated) == len(containers) and not any(will_restart(c) for c in terminated):
        failed = [c for c in containers if c.get("exitCode", 0) != 0]
        if not failed:
            return ["Succeeded", "Completed"]
        return ["Failed", failed[0].get("reason") or "Error"]
    running = any(c["state"] == "running" for c in containers)
    restarting = any(will_restart(c) for c in terminated)
    crashloop = any(c["state"] == "waiting" and c.get("reason") == "CrashLoopBackOff" for c in containers)
    phase = "Running" if (running or restarting or crashloop) else "Pending"
    for c in containers:
        if c["state"] == "waiting" and c.get("reason"):
            return [phase, c["reason"]]
    return [phase, phase]

