    # return [[start, end], ...] for the jobs that actually run
    pass

k8s-cronjob-concurrency.solution:
def cronRuns(starts, durations, policy):
    runs = []
    for s, d in zip(starts, durations):
        if runs and policy != "Allow" and s < runs[-1][1]:
            if policy == "Forbid":
                continue
            runs[-1][1] = s
        runs.append([s, s + d])
    return runs
